const composeRe = new RegExp('(?:' + L + '(?:soạn|viết|tạo|làm|chuẩn bị|draft)\\s+(?:giúp\\s+|cho\\s+(?:tôi|mình|em)\\s+)?(?:một\\s+|1\\s+|lại\\s+)?(?:bản\\s+)?(?:thư|mail|email|thông báo|bản nháp|nội dung|tin)' + R + '|' + L + '(?:báo|thông báo|nhắn|nhắc)\\s+(?:cho\\s+)?(?:mọi|tất cả|các|những|toàn bộ|người)' + R + ')', 'u');
const confirmed = text.length > 0 && text.length <= 200 && !/[?？]/.test(text) && cancelRe.test(text) && !negatedRe.test(text) && !composeRe.test(text);
