  return stop('needs_admin_confirmation', 'Tin nhắn hiện tại của admin chưa yêu cầu hủy rõ ràng (ví dụ "hủy thông báo này", "dừng gửi"). Hãy dừng lại và hỏi admin có chắc muốn hủy không; chỉ hủy khi họ nói rõ trong tin nhắn của họ. Thư đã gửi đi không thu hồi được.');
}
