const MIGRATION_MESSAGE = 'Chức năng thông báo chưa sẵn sàng (cơ sở dữ liệu chưa cập nhật). Báo admin chạy migration.';
const GENERIC_MESSAGE = 'Chức năng thông báo tạm thời không dùng được (lỗi kết nối hoặc cơ sở dữ liệu Supabase). Dừng và báo admin kiểm tra Supabase và tab Executions của n8n.';
const unavailable = (message) => [{ json: { status: 'service_unavailable', message } }];
