  not_found: 'Không tìm thấy thông báo này trong cuộc trò chuyện hiện tại. Kiểm tra lại id hoặc dùng get_announcement_status để xem thông báo mới nhất.',
  invalid_input: 'Dữ liệu gửi lên không hợp lệ. Sửa lại theo mô tả tool rồi thử lại, hoặc hỏi admin nếu thiếu thông tin.',
};
const describe = (r) => {
  if (r.status === 'cancelled') return 'Đã hủy thông báo: ' + num(r.skipped, 0) + ' người chưa nhận sẽ không còn được gửi; ' + num(r.sent_count, 0) + ' thư đã gửi đi không thu hồi được.';
  if (r.status === 'already_sent') return 'Thông báo đã gửi xong nên không thể hủy; thư đã gửi không thu hồi được.';
  if (r.status === 'already_cancelled') return 'Thông báo này đã hủy từ trước, không cần làm gì thêm.';
  return null;
};
const found = describe(b);
const info = typeof found === 'string' ? { message: found } : found;
const { message, ...extra } = info || {};
